<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Pterodactyl\Models\Server; use Illuminate\Http\JsonResponse; use Pterodactyl\Facades\Activity; use Illuminate\Support\Facades\Cache; use Pterodactyl\Services\Dezerx\DayZ\DayZMods; use Pterodactyl\Services\Dezerx\ServerVariables; use Pterodactyl\Services\Dezerx\DayZ\DayZWorkshop; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\AddonRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\AddonDeleteRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\AddonInstallRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\DayZModsWriteRequest; class DayZModController extends ClientApiController { private const INSPECT = 40; public function __construct(private readonly DayZWorkshop $workshop) { parent::__construct(); } public function index(AddonRequest $request, Server $server): JsonResponse { if (DayZMods::definition($server, DayZMods::CLIENT) === null) { return new JsonResponse(['available' => false]); } $files = new ServerFiles($server); $folders = DayZMods::folders($files) ?? []; $serverKeys = DayZMods::serverKeys($files); $lists = []; foreach (DayZMods::SIDES as $side => $key) { $lists[$side] = DayZMods::entries($server, $key); } $modFile = DayZMods::modFileIds($files, $server); $ids = $modFile; foreach ($lists as $entries) { foreach ($entries as $entry) { if ($entry['token'] !== null && ($id = DayZMods::workshopId($entry['token'])) !== null) { $ids[] = $id; } } } foreach (array_keys($folders) as $name) { if (($id = DayZMods::workshopId($name)) !== null) { $ids[] = $id; } } $details = $this->workshop->details($ids); $inspected = 0; $present = function (string $folder) use ($files, $server, $folders, $details, $serverKeys, &$inspected): array { return $this->present($files, $server, $folder, $folders, $details, $serverKeys, $inspected); }; $out = []; $loaded = []; $order = []; foreach ($lists as $side => $entries) { $reachable = array_column(DayZMods::reachable($entries), 'raw'); $honoured = DayZMods::honoursOrder($server, $side); $order[$side] = $honoured; if (!$honoured) { $position = array_flip(DayZMods::sortedOrder($entries)); usort($entries, fn ($a, $b) => ($position[$a['raw']] ?? PHP_INT_MAX) <=> ($position[$b['raw']] ?? PHP_INT_MAX)); } $out[$side] = array_map(function (array $entry) use ($present, $side, $reachable, &$loaded) { $cut = in_array($entry['raw'], $reachable, true) ? null : (preg_match('/\s/', $entry['raw']) === 1 ? 'breaks' : 'after'); if ($entry['token'] === null) { return ['raw' => $entry['raw'], 'folder' => null, 'side' => $side, 'kind' => 'unknown', 'cut' => $cut]; } $loaded[$entry['token']] = true; return ['raw' => $entry['raw'], 'side' => $side, 'cut' => $cut] + $present($entry['token']); }, $entries); } $fileCut = count(DayZMods::reachable($lists['client'])) < count($lists['client']) ? 'after' : null; $fromFile = array_map(function (string $id) use ($present, $fileCut, &$loaded) { $loaded['@' . $id] = true; return ['raw' => '@' . $id, 'side' => 'client', 'cut' => $fileCut] + $present('@' . $id); }, $modFile); $unloaded = []; foreach ($folders as $name => $folder) { if (!isset($loaded[$name]) && DayZMods::folder($name) !== null) { $unloaded[] = ['raw' => $name, 'side' => null] + $present($name); } } return new JsonResponse([ 'available' => true, 'editable' => [ 'client' => DayZMods::editable($server, DayZMods::CLIENT), 'server' => DayZMods::editable($server, DayZMods::SERVER), ], 'downloads' => trim((string) ServerVariables::value($server, DayZMods::NO_DOWNLOADS)) !== '1', 'orderHonoured' => $order, 'search' => $this->workshop->configured() ? 'api' : 'pages', 'state' => $files->powerStateOrNull(), 'lists' => $out, 'modFile' => $modFile === [] ? null : [ 'name' => (string) ServerVariables::value($server, DayZMods::MOD_FILE), 'mods' => $fromFile, ], 'unloaded' => $unloaded, ]); } private function present(ServerFiles $files, Server $server, string $folder, array $folders, array $details, array $serverKeys, int &$inspected): array { $id = DayZMods::workshopId($folder); $item = $id !== null ? ($details[$id] ?? null) : null; $disk = $folders[$folder] ?? null; $name = $item['title'] ?? null; $keys = null; if ($disk !== null && $inspected < self::INSPECT) { $inspected++; $stamp = $disk['modifiedAt'] ?? 0; [$keys, $metaName] = Cache::remember( "dezerx:dayz:folder:{$server->uuid}:" . md5($folder) . ":{$stamp}", 600, fn () => [ array_column(DayZMods::modKeys($files, $folder), 'name'), $id === null ? DayZMods::metaName($files, $folder) : null, ], ); $name ??= $metaName; } $missing = $keys === null ? [] : array_values(array_filter($keys, fn ($key) => !isset($serverKeys[mb_strtolower($key)]))); return [ 'folder' => $folder, 'kind' => $id !== null ? 'workshop' : 'upload', 'workshopId' => $id, 'name' => $name ?? ltrim($folder, '@'), 'preview' => $item['preview'] ?? null, 'size' => $item['size'] ?? null, 'url' => $item['url'] ?? null, 'updatedAt' => $item['updatedAt'] ?? null, 'subscriptions' => $item['subscriptions'] ?? null, 'known' => $id === null || $item !== null, 'onDisk' => $disk !== null, 'folderModifiedAt' => $disk['modifiedAt'] ?? null, 'updateAvailable' => $disk !== null && $item !== null && ($disk['modifiedAt'] ?? 0) > 0 && ($item['updatedAt'] ?? 0) > ($disk['modifiedAt'] ?? 0), 'keys' => $keys, 'missingKeys' => $missing, ]; } public function search(AddonRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'query' => ['nullable', 'string', 'max:100'], 'page' => ['nullable', 'integer', 'min:1', 'max:50'], ]); return new JsonResponse($this->workshop->search((string) ($data['query'] ?? ''), (int) ($data['page'] ?? 1))); } public function item(AddonRequest $request, Server $server): JsonResponse { $data = $request->validate(['id' => ['required', 'string', 'max:300']]); $id = DayZWorkshop::idFrom($data['id']); if ($id === null) { return $this->refuse('NotWorkshop', 'That is not a Steam Workshop ID or link.'); } $collection = $this->workshop->collection($id); if ($collection !== null) { $details = $this->workshop->details($collection); return new JsonResponse([ 'item' => null, 'collection' => ['id' => $id, 'items' => array_values(array_filter(array_map(fn ($child) => $details[$child] ?? null, $collection)))], 'requires' => [], ]); } $item = $this->workshop->details([$id])[$id] ?? null; if ($item === null) { return $this->refuse('NotFound', 'Steam has no DayZ Workshop item with that ID. It may be private, removed, or for another game.', 404); } $requires = $this->workshop->requires($id); $details = $this->workshop->details($requires); return new JsonResponse([ 'item' => $item, 'collection' => null, 'requires' => array_values(array_filter(array_map(fn ($child) => $details[$child] ?? null, $requires))), ]); } public function add(DayZModsWriteRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'ids' => ['required', 'array', 'min:1', 'max:120'], 'ids.*' => ['required', 'string', 'regex:/^[0-9]{1,20}$/'], 'side' => ['required', 'in:client,server'], ]); $known = $this->workshop->details($data['ids']); $folders = []; foreach ($data['ids'] as $id) { $id = ltrim($id, '0'); if ($id !== '' && isset($known[$id])) { $folders[] = '@' . $id; } } if ($folders === []) { return $this->refuse('NotFound', 'None of those are DayZ Workshop items Steam knows about.', 404); } return $this->append($server, $data['side'], $folders, 'server:dayz-mod.add'); } public function load(DayZModsWriteRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'folder' => ['required', 'string', 'max:70'], 'side' => ['required', 'in:client,server'], ]); $folder = DayZMods::folder($data['folder']); if ($folder === null) { return $this->refuse('BadFolder', 'Mod folders start with @ and may only use letters, numbers, dots, dashes and underscores, so the start script can load them.'); } return $this->append($server, $data['side'], [$folder], 'server:dayz-mod.load'); } private function append(Server $server, string $side, array $folders, string $event): JsonResponse { $key = DayZMods::SIDES[$side]; if (!DayZMods::editable($server, $key)) { return $this->locked($key); } $entries = DayZMods::entries($server, $key); $added = []; foreach ($folders as $folder) { if (DayZMods::sideOf($server, $folder) === null && !in_array($folder, $added, true)) { $entries[] = ['raw' => $folder, 'token' => $folder]; $added[] = $folder; } } if ($added !== [] && !DayZMods::write($server, $key, $entries)) { return $this->refused($key); } if ($added !== []) { Activity::event($event)->subject($server)->property(['side' => $side, 'mods' => $added])->log(); } return new JsonResponse(['added' => $added]); } public function order(DayZModsWriteRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'side' => ['required', 'in:client,server'], 'order' => ['present', 'array', 'max:120'], 'order.*' => ['string', 'max:200'], ]); $key = DayZMods::SIDES[$data['side']]; if (!DayZMods::editable($server, $key)) { return $this->locked($key); } $entries = DayZMods::entries($server, $key); $byRaw = []; foreach ($entries as $entry) { $byRaw[$entry['raw']] = $entry; } if (!DayZMods::honoursOrder($server, $data['side'])) { return $this->refuse('Sorted', 'This server loads mods in name order, so the order cannot be changed here.', 409); } $order = array_values($data['order']); $current = array_keys($byRaw); $sorted = $order; sort($sorted); sort($current); if ($sorted !== $current) { return $this->refuse('Changed', 'The mod list changed while you were sorting it. Reload the page and try again.', 409); } if (!DayZMods::write($server, $key, array_map(fn ($raw) => $byRaw[$raw], $order))) { return $this->refused($key); } Activity::event('server:dayz-mod.order')->subject($server)->property(['side' => $data['side']])->log(); return new JsonResponse(['order' => $order]); } public function move(DayZModsWriteRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'folder' => ['required', 'string', 'max:70'], 'to' => ['required', 'in:client,server'], ]); $folder = DayZMods::folder($data['folder']); $from = $data['to'] === 'client' ? 'server' : 'client'; if ($folder === null || DayZMods::sideOf($server, $folder) !== $from) { return $this->refuse('NotLoaded', 'That mod is not on the other list any more. Reload the page.', 409); } foreach ([DayZMods::SIDES[$from], DayZMods::SIDES[$data['to']]] as $key) { if (!DayZMods::editable($server, $key)) { return $this->locked($key); } } $source = array_values(array_filter(DayZMods::entries($server, DayZMods::SIDES[$from]), fn ($entry) => $entry['raw'] !== $folder)); $target = DayZMods::entries($server, DayZMods::SIDES[$data['to']]); $target[] = ['raw' => $folder, 'token' => $folder]; if (!DayZMods::write($server, DayZMods::SIDES[$data['to']], $target)) { return $this->refused(DayZMods::SIDES[$data['to']]); } if (!DayZMods::write($server, DayZMods::SIDES[$from], $source)) { return $this->refused(DayZMods::SIDES[$from]); } Activity::event('server:dayz-mod.move')->subject($server)->property(['mod' => $folder, 'to' => $data['to']])->log(); return new JsonResponse(['folder' => $folder, 'side' => $data['to']]); } public function remove(DayZModsWriteRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'raw' => ['required', 'string', 'max:200'], 'side' => ['required', 'in:client,server'], ]); $key = DayZMods::SIDES[$data['side']]; if (!DayZMods::editable($server, $key)) { return $this->locked($key); } $entries = DayZMods::entries($server, $key); $kept = array_values(array_filter($entries, fn ($entry) => $entry['raw'] !== $data['raw'])); if (count($kept) === count($entries)) { return $this->refuse('NotLoaded', 'That mod is not on the list any more. Reload the page.', 409); } if (!DayZMods::write($server, $key, $kept)) { return $this->refused($key); } Activity::event('server:dayz-mod.remove')->subject($server)->property(['side' => $data['side'], 'mod' => $data['raw']])->log(); return new JsonResponse(['removed' => $data['raw']]); } public function keys(AddonInstallRequest $request, Server $server): JsonResponse { $files = new ServerFiles($server); $folders = DayZMods::folders($files) ?? []; $loaded = []; foreach (DayZMods::SIDES as $key) { foreach (DayZMods::entries($server, $key) as $entry) { if ($entry['token'] !== null && isset($folders[$entry['token']])) { $loaded[] = $entry['token']; } } } foreach (DayZMods::modFileIds($files, $server) as $id) { if (isset($folders['@' . $id])) { $loaded[] = '@' . $id; } } $copied = []; foreach (array_slice(array_values(array_unique($loaded)), 0, self::INSPECT) as $folder) { array_push($copied, ...DayZMods::syncKeys($files, $folder)); } if ($copied !== []) { Activity::event('server:dayz-mod.keys')->subject($server)->property(['keys' => $copied])->log(); } return new JsonResponse(['copied' => $copied]); } public function destroy(AddonDeleteRequest $request, Server $server): JsonResponse { $data = $request->validate(['folder' => ['required', 'string', 'max:70']]); $folder = DayZMods::folder($data['folder']); if ($folder === null) { return $this->refuse('BadFolder', 'That is not a mod folder.'); } $files = new ServerFiles($server); $loadedByFile = ($id = DayZMods::workshopId($folder)) !== null && in_array($id, DayZMods::modFileIds($files, $server), true); if (DayZMods::sideOf($server, $folder) !== null || $loadedByFile) { return $this->refuse('StillLoaded', 'Take the mod off its list before deleting its files, or the server will fail to start.', 409); } if (!$files->deletePaths('/', [$folder])) { return $this->refuse('DeleteFailed', 'The node could not delete that folder.', 502); } Activity::event('server:dayz-mod.delete')->subject($server)->property(['mod' => $folder])->log(); return new JsonResponse(['deleted' => $folder]); } private function locked(string $key): JsonResponse { return $this->refuse('Locked', "The host has locked {$key} on this server's egg, so the mod list cannot be changed here.", 403); } private function refused(string $key): JsonResponse { return $this->refuse('WriteFailed', "{$key} was refused by the egg's own rules for it."); } private function refuse(string $code, string $detail, int $status = 422): JsonResponse { return new JsonResponse(['errors' => [['code' => $code, 'status' => (string) $status, 'detail' => $detail]]], $status); } } 